-- ============================================
-- Portal_Sales_AJI - which recent migrations (064-096) this database has. Read-only.
-- Run it on the database named in .env.local (DB_SERVER / DB_DATABASE).
-- ============================================
SET NOCOUNT ON;

SELECT
    @@SERVERNAME AS [Server],
    DB_NAME() AS [Database];

SELECT T0.[Migration], CASE WHEN T0.[Done] = 1 THEN 'YES' ELSE 'MISSING' END AS [Applied]
FROM (
    SELECT '064_create_fts11odsh' AS [Migration], CASE WHEN OBJECT_ID('FTS11ODSH') IS NOT NULL THEN 1 ELSE 0 END AS [Done]
    UNION ALL SELECT '065_lead_tmpr_created_by', CASE WHEN COL_LENGTH('FTS11LEAD', 'CreatedBy') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '067_line_is_foc', CASE WHEN COL_LENGTH('FTS11QUT1', 'IsFOC') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '068_fts11oadm_default_price_list', CASE WHEN COL_LENGTH('FTS11OADM', 'DefaultPriceList') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '069_line_visorder', CASE WHEN COL_LENGTH('FTS11QUT1', 'VisOrder') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '070_create_fts11ocrd', CASE WHEN OBJECT_ID('FTS11OCRD') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '071_create_fts11orin_rin1', CASE WHEN OBJECT_ID('FTS11ORIN') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '072_fts11nnm1_ismanual', CASE WHEN COL_LENGTH('FTS11NNM1', 'IsManual') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '074_salesdoc_groupnum', CASE WHEN COL_LENGTH('FTS11ORDR', 'GroupNum') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '075_fn_unreconciled_docs_downpayment', CASE WHEN OBJECT_DEFINITION(OBJECT_ID('dbo.FTS_fn_UnreconciledDocs')) LIKE '%''203''%' THEN 1 ELSE 0 END
    UNION ALL SELECT '076_tmpr_dates', CASE WHEN COL_LENGTH('FTS11TMPR', 'DocDate') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '077_fts11ocrd_groupcode', CASE WHEN COL_LENGTH('FTS11OCRD', 'GroupCode') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '078_create_fts11crd2', CASE WHEN OBJECT_ID('FTS11CRD2', 'U') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '079_add_streetno', CASE WHEN COL_LENGTH('FTS11CRD2', 'StreetNo') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '080_fts11crd2_deliveryzone', CASE WHEN COL_LENGTH('FTS11CRD2', 'DeliveryZone') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '081_salesdoc_coa', CASE WHEN COL_LENGTH('FTS11ORDR', 'COA') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '082_branch', CASE WHEN COL_LENGTH('SystemUsers', 'Branch') IS NOT NULL AND COL_LENGTH('FTS11ORIN', 'Branch') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '083_salesdoc_incomments_tac', CASE WHEN COL_LENGTH('FTS11ORDR', 'TAC') IS NOT NULL AND COL_LENGTH('FTS11ORIN', 'InComments') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '084_approval_round_changes', CASE WHEN COL_LENGTH('FTS11WDD1', 'Round') IS NOT NULL AND OBJECT_ID('FTS11WDD2') IS NOT NULL AND COL_LENGTH('FTS11OCRD', 'BaseEntry') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '085_approval_email', CASE WHEN COL_LENGTH('FTS11OADM', 'ApprEmail') IS NOT NULL AND COL_LENGTH('FTS11OADM', 'PortalUrl') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '086_salesdoc_line_salesqty', CASE WHEN COL_LENGTH('FTS11QUT1', 'SalesQty') IS NOT NULL AND COL_LENGTH('FTS11RDR1', 'SalesUoM') IS NOT NULL AND COL_LENGTH('FTS11RIN1', 'SalesUoM') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '087_salesdoc_currency', CASE WHEN COL_LENGTH('FTS11OQUT', 'DocCur') IS NOT NULL AND COL_LENGTH('FTS11ORDR', 'DocTotalFC') IS NOT NULL AND COL_LENGTH('FTS11RIN1', 'TotalFrgn') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '088_receipt_currency', CASE WHEN COL_LENGTH('FTS11TMPR', 'DocCur') IS NOT NULL AND COL_LENGTH('FTS11OTRQ', 'DocTotalFC') IS NOT NULL AND COL_LENGTH('FTS11TMP1', 'DocCur') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '089_lead_currency', CASE WHEN COL_LENGTH('FTS11LEAD', 'Currency') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '090_salesdoc_disctype', CASE WHEN ISNULL(COL_LENGTH('FTS11OQUT', 'DiscType'), COL_LENGTH('FTS11OQUT', 'DiscType1')) IS NOT NULL AND ISNULL(COL_LENGTH('FTS11ORDR', 'DiscType'), COL_LENGTH('FTS11ORDR', 'DiscType1')) IS NOT NULL AND ISNULL(COL_LENGTH('FTS11ORIN', 'DiscType'), COL_LENGTH('FTS11ORIN', 'DiscType1')) IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '091_salesdoc_address', CASE WHEN COL_LENGTH('FTS11OQUT', 'Address2') IS NOT NULL AND COL_LENGTH('FTS11ORDR', 'ShipToCode') IS NOT NULL AND COL_LENGTH('FTS11ORIN', 'PayToCode') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '092_salesdoc_disctype5', CASE WHEN COL_LENGTH('FTS11OQUT', 'DiscType5') IS NOT NULL AND COL_LENGTH('FTS11ORDR', 'DiscType1') IS NOT NULL AND COL_LENGTH('FTS11ORIN', 'DiscType3') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '093_salesdoc_bankinfo', CASE WHEN COL_LENGTH('FTS11OQUT', 'BankInfo') IS NOT NULL AND COL_LENGTH('FTS11ORDR', 'BankInfo') IS NOT NULL AND COL_LENGTH('FTS11ORIN', 'BankInfo') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '094_salesdoc_address_lines', CASE WHEN COL_LENGTH('FTS11OQUT', 'ShipDeliveryZone') IS NOT NULL AND COL_LENGTH('FTS11ORDR', 'ShipDeliveryZone') IS NOT NULL AND COL_LENGTH('FTS11ORIN', 'ShipDeliveryZone') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '095_layout_email', CASE WHEN COL_LENGTH('FTS11SLYT', 'EmailAllowed') IS NOT NULL AND COL_LENGTH('FTS11OEML', 'LayoutEntry') IS NOT NULL THEN 1 ELSE 0 END
    UNION ALL SELECT '096_salesdoc_line_exportprice', CASE WHEN COL_LENGTH('FTS11QUT1', 'SalesPrice') IS NOT NULL AND COL_LENGTH('FTS11RDR1', 'SalesPrice') IS NOT NULL AND COL_LENGTH('FTS11RIN1', 'SalesPrice') IS NOT NULL THEN 1 ELSE 0 END
) T0;
